                return (x, y)
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def toward(a, b):
        return [clamp(b[0] - a[0]), clamp(b[1] - a[1])]

    def safe_seq(v):
        return v if isinstance(v, (list, tuple)) else []

    def collect_positions(*keys):
